27	constexpr uint32_t kArgIndexRemoteEngine = 3;
28	constexpr size_t kMemSize = 2 * 1024UL * 1024UL;
29	constexpr size_t kWriteSize = 1024UL * 1024UL;
30	constexpr size_t kTimeoutInMillis = 60000;
31	
32	#define CHECK_ACL(x)                                                                  \
33	  do {                                                                                \
34	    aclError __ret = x;                                                               \
35	    if (__ret != ACL_ERROR_NONE) {                                                    \
36	      std::cerr << __FILE__ << ":" << __LINE__ << " aclError:" << __ret << std::endl; \
37	      return -1;                                                                      \
38	    }                                                                                 \
39	  } while (0)
