50	int Initialize(Hixl &hixl_engine, const char *local_engine) {
51	  std::map<AscendString, AscendString> options;
52	  options[OPTION_ENABLE_USE_FABRIC_MEM] = "1";
53	  auto ret = hixl_engine.Initialize(local_engine, options);
54	  if (ret != SUCCESS) {
55	    printf("[ERROR] Initialize failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
56	    return -1;
57	  }
58	  printf("[INFO] Initialize success\n");
59	  return 0;
60	}
61	
62	int Connect(Hixl &hixl_engine, const char *remote_engine) {
63	  auto ret = hixl_engine.Connect(remote_engine);
64	  if (ret != SUCCESS) {
65	    printf("[ERROR] Connect failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
66	    return -1;
67	  }
68	  printf("[INFO] Connect success\n");
69	  return 0;
70	}
71	
72	bool FileExists(const std::string &name) {
73	  return std::ifstream(name).good();
74	}
75	
76	bool WaitFile(const std::string &name) {
77	  auto start = std::chrono::steady_clock::now();
78	  while (!FileExists(name)) {
79	    uint64_t time_cost =
80	        std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count();
81	    if (time_cost > kTimeoutInMillis) {
82	      printf("[ERROR] Wait file:%s timeout.\n", name.c_str());
83	      return false;
84	    }
85	    std::this_thread::sleep_for(std::chrono::seconds(1));
86	  }
87	  return true;
88	}
89	
90	int32_t Transfer(Hixl &hixl_engine, void *va, const char *local_engine, const char *remote_engine,
91	                 uint32_t &remote_dev_id) {
92	  if (!WaitFile(remote_engine)) {
93	    return -1;
94	  }
95	  uintptr_t remote_addr;
96	  std::ifstream(remote_engine) >> remote_addr >> remote_dev_id;
97	
98	  printf("[INFO] Local engine test write, remote engine:%s\n", remote_engine);
99	  // Write local first 512K to remote last 512K
100	  TransferOpDesc desc{reinterpret_cast<uintptr_t>(va), reinterpret_cast<uintptr_t>(remote_addr) + kWriteSize,
101	                      kWriteSize};
102	  auto ret = hixl_engine.TransferSync(remote_engine, WRITE, {desc});
103	  if (ret != SUCCESS) {
104	    printf("[ERROR] TransferSync write failed, remote_addr:%lu, ret = %u, errmsg: %s\n", remote_addr, ret,
105	           GetRecentErrMsg());
106	    return -1;
107	  }
108	  printf("[INFO] TransferSync write success, remote_addr:%lu, value:%s\n", remote_addr, local_engine);
109	  return 0;
110	}
111	
112	void Finalize(Hixl &hixl_engine, bool connected, const char *remote_engine, const std::vector<MemHandle> handles) {
113	  if (connected) {
114	    auto ret = hixl_engine.Disconnect(remote_engine);
115	    if (ret != 0) {
116	      printf("[ERROR] Disconnect failed, ret = %d, errmsg: %s\n", ret, GetRecentErrMsg());
117	    } else {
118	      printf("[INFO] Disconnect success\n");
119	    }
120	  }
121	  for (auto handle : handles) {
122	    auto ret = hixl_engine.DeregisterMem(handle);
123	    if (ret != 0) {
124	      printf("[ERROR] DeregisterMem failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
125	    } else {
126	      printf("[INFO] DeregisterMem success\n");
127	    }
128	  }
129	  hixl_engine.Finalize();
130	}
131	
132	int AllocateBuffer(int32_t device_id, size_t mem_size, void *&va, aclrtDrvMemHandle &pa_handle) {
133	  CHECK_ACL(aclrtReserveMemAddress(&va, mem_size, 0, nullptr, 1));
134	  aclrtPhysicalMemProp prop{};
135	  prop.handleType = ACL_MEM_HANDLE_TYPE_NONE;
136	  prop.allocationType = ACL_MEM_ALLOCATION_TYPE_PINNED;
137	  prop.reserve = 0;
138	  prop.memAttr = ACL_HBM_MEM_HUGE;
139	  prop.location.type = ACL_MEM_LOCATION_TYPE_DEVICE;
140	  prop.location.id = device_id;
141	  CHECK_ACL(aclrtMallocPhysical(&pa_handle, mem_size, &prop, 0));
142	  CHECK_ACL(aclrtMapMem(va, mem_size, 0, pa_handle, 0));
143	  void *host_data;
144	  CHECK_ACL(aclrtMallocHost(&host_data, mem_size));
145	  memset_s(host_data, mem_size, device_id, mem_size);
146	  CHECK_ACL(aclrtMemcpy(va, kMemSize, host_data, mem_size, ACL_MEMCPY_HOST_TO_DEVICE));
147	  CHECK_ACL(aclrtFreeHost(host_data));
148	  return 0;
149	}
150	
151	int VerifyBuffer(void *va, int32_t expected_val) {
152	  void *host_data;
153	  CHECK_ACL(aclrtMallocHost(&host_data, kWriteSize));
154	  // Check the second half of the buffer
155	  void *dev_ptr = reinterpret_cast<void *>(reinterpret_cast<uintptr_t>(va) + kWriteSize);
156	  CHECK_ACL(aclrtMemcpy(host_data, kWriteSize, dev_ptr, kWriteSize, ACL_MEMCPY_DEVICE_TO_HOST));
157	
158	  uint8_t *data = static_cast<uint8_t *>(host_data);
159	  uint8_t val = static_cast<uint8_t>(expected_val);
160	  for (size_t i = 0; i < kWriteSize; ++i) {
161	    if (data[i] != val) {
162	      printf("[ERROR] Verify failed, index:%zu, expected:%u, actual:%u\n", i, val, data[i]);
163	      CHECK_ACL(aclrtFreeHost(host_data));
164	      return -1;
165	    }
166	  }
167	  CHECK_ACL(aclrtFreeHost(host_data));
168	  printf("[INFO] Verify success, value:%u\n", val);
169	  return 0;
170	}
171	
172	int32_t TransferAndVerify(Hixl &hixl_engine, void *va, const char *local_engine, const char *remote_engine,
173	                          MemHandle &handle) {
174	  bool connected = true;
175	  uint32_t remote_dev_id = 0;
176	  if (Transfer(hixl_engine, va, local_engine, remote_engine, remote_dev_id) != 0) {
177	    Finalize(hixl_engine, connected, remote_engine, {handle});
178	    return -1;
179	  }
180	
181	  std::string local_done_file = std::string(local_engine) + ".done";
182	  std::ofstream done_file(local_done_file);
183	  if (done_file) {
184	    done_file << "done" << std::endl;
185	    done_file.close();
186	  }
187	  std::string remote_done_file = std::string(remote_engine) + ".done";
188	  printf("[INFO] Wait for remote write done signal:%s\n", remote_done_file.c_str());
189	  if (!WaitFile(remote_done_file)) {
190	    printf("[ERROR] Wait remote write done failed.\n");
191	    Finalize(hixl_engine, connected, remote_engine, {handle});
192	    return -1;
193	  }
194	
195	  if (VerifyBuffer(va, remote_dev_id) != 0) {
196	    Finalize(hixl_engine, connected, remote_engine, {handle});
197	    return -1;
198	  }
199	  Finalize(hixl_engine, connected, remote_engine, {handle});
200	  printf("[INFO] run Sample end\n");
201	  return 0;
202	}
203	
204	int32_t Run(int32_t device_id, const char *local_engine, const char *remote_engine) {
205	  printf("[INFO] run start\n");
206	  Hixl hixl_engine;
207	  if (Initialize(hixl_engine, local_engine) != 0) {
208	    printf("[ERROR] Initialize Hixl failed\n");
209	    return -1;
210	  }
211	  void *va;
212	  aclrtDrvMemHandle pa_handle;
213	  if (AllocateBuffer(device_id, kMemSize, va, pa_handle) != 0) {
214	    printf("[ERROR] allocate failed, dev_id: %d\n", device_id);
215	    return -1;
216	  }
217	  MemDesc desc{};
218	  desc.addr = reinterpret_cast<uintptr_t>(va);
219	  desc.len = kMemSize;
220	  MemHandle handle = nullptr;
221	  bool connected = false;
222	  auto ret = hixl_engine.RegisterMem(desc, MEM_DEVICE, handle);
223	  if (ret != SUCCESS) {
224	    printf("[ERROR] RegisterMem failed, ret = %u, errmsg: %s\n", ret, GetRecentErrMsg());
225	    Finalize(hixl_engine, connected, remote_engine, {});
226	    return -1;
227	  }
228	  printf("[INFO] RegisterMem success.\n");
229	  std::ofstream tmp_file(local_engine);
230	  if (tmp_file) {
231	    tmp_file << reinterpret_cast<uintptr_t>(va) << " " << device_id << std::endl;
232	    tmp_file.close();
233	  }
234	  std::string local_init_done_file = std::string(local_engine) + ".init_done";
235	  std::ofstream init_done_file(local_init_done_file);
236	  if (init_done_file) {
237	    init_done_file << "done" << std::endl;
238	    init_done_file.close();
239	  }
240	  std::string remote_init_done_file = std::string(remote_engine) + ".init_done";
241	  printf("[INFO] Wait for remote write done signal:%s\n", remote_init_done_file.c_str());
242	  if (!WaitFile(remote_init_done_file)) {
243	    printf("[ERROR] Wait remote write done failed.\n");
244	    Finalize(hixl_engine, connected, remote_engine, {handle});
245	    return -1;
246	  }
247	  if (Connect(hixl_engine, remote_engine) != 0) {
248	    Finalize(hixl_engine, connected, remote_engine, {handle});
249	    return -1;
250	  }
251	  return TransferAndVerify(hixl_engine, va, local_engine, remote_engine, handle);
252	}
253	
254	int main(int32_t argc, char **argv) {
255	  std::string device_id;
256	  std::string local_engine;
257	  std::string remote_engine;
258	  if (argc == kExpectedArgCnt) {
259	    device_id = argv[kArgIndexDeviceId];
260	    local_engine = argv[kArgIndexLocalEngine];
261	    remote_engine = argv[kArgIndexRemoteEngine];
262	    printf("[INFO] device_id = %s, local_engine = %s, remote_engine = %s\n", device_id.c_str(), local_engine.c_str(),
263	           remote_engine.c_str());
264	  } else {
265	    printf("[ERROR] expect 3 args(device_id, local_engine, remote_engine), but got %d\n", argc - 1);
266	    return -1;
267	  }
268	  CHECK_ACL(aclInit(nullptr));
269	  int32_t device = std::stoi(device_id);
270	  CHECK_ACL(aclrtSetDevice(device));
271	  int32_t ret = Run(device, local_engine.c_str(), remote_engine.c_str());
272	  CHECK_ACL(aclrtResetDevice(device));
273	  aclFinalize();
274	  return ret;
275	}
